//! GET /notes with its `tag`, `q`, `after` and `limit` query parameters.

const std = @import("std");
const Context = @import("../http/Context.zig");
const list_db = @import("../db/list.zig");

/// GET /notes
pub fn list(ctx: *Context) Context.Error!void {
    const filter = try readFilter(ctx) orelse return;
    const notes = blk: {
        const db = ctx.store.acquire();
        defer ctx.store.release();
        break :blk try list_db.list(db, ctx.arena, filter);
    };
    try ctx.sendJson(.ok, .{ .notes = notes });
}

/// Reads the filter from the query parameters. Answers 400 and returns null
/// if `after` or `limit` is invalid.
fn readFilter(ctx: *Context) Context.Error!?list_db.Filter {
    var filter: list_db.Filter = .{
        .tag = try ctx.queryParam("tag"),
        .text = try ctx.queryParam("q"),
    };
    if (try ctx.queryParam("after")) |text| {
        filter.after = parseAfter(text) orelse {
            try ctx.sendError(.bad_request, "after must be an integer");
            return null;
        };
    }
    if (try ctx.queryParam("limit")) |text| {
        filter.limit = parseLimit(text) orelse {
            try ctx.sendError(.bad_request, std.fmt.comptimePrint(
                "limit must be an integer from 1 to {d}",
                .{list_db.max_limit},
            ));
            return null;
        };
    }
    return filter;
}

/// Parses `after`: a decimal integer with an optional leading `-`.
fn parseAfter(text: []const u8) ?i64 {
    const digits = if (std.mem.startsWith(u8, text, "-")) text[1..] else text;
    if (!isDecimal(digits)) return null;
    return std.fmt.parseInt(i64, text, 10) catch null;
}

/// Parses `limit`: a decimal integer from 1 to `max_limit`.
fn parseLimit(text: []const u8) ?u32 {
    if (!isDecimal(text)) return null;
    const limit = std.fmt.parseInt(u32, text, 10) catch return null;
    return if (limit >= 1 and limit <= list_db.max_limit) limit else null;
}

/// Whether `text` is a non-empty run of ASCII digits. `std.fmt.parseInt`
/// also accepts a `+` sign and `_` separators, which are not valid here.
fn isDecimal(text: []const u8) bool {
    if (text.len == 0) return false;
    for (text) |ch| if (!std.ascii.isDigit(ch)) return false;
    return true;
}

const testing = std.testing;

test parseAfter {
    try testing.expectEqual(@as(?i64, 0), parseAfter("0"));
    try testing.expectEqual(@as(?i64, 2), parseAfter("2"));
    try testing.expectEqual(@as(?i64, 7), parseAfter("007"));
    try testing.expectEqual(@as(?i64, -3), parseAfter("-3"));
    try testing.expectEqual(@as(?i64, std.math.maxInt(i64)), parseAfter("9223372036854775807"));
    try testing.expectEqual(@as(?i64, std.math.minInt(i64)), parseAfter("-9223372036854775808"));
    try testing.expectEqual(null, parseAfter("9223372036854775808"));
    try testing.expectEqual(null, parseAfter(""));
    try testing.expectEqual(null, parseAfter("-"));
    try testing.expectEqual(null, parseAfter("+1"));
    try testing.expectEqual(null, parseAfter("--1"));
    try testing.expectEqual(null, parseAfter("1_0"));
    try testing.expectEqual(null, parseAfter("1.5"));
    try testing.expectEqual(null, parseAfter(" 1"));
    try testing.expectEqual(null, parseAfter("abc"));
}

test parseLimit {
    try testing.expectEqual(@as(?u32, 1), parseLimit("1"));
    try testing.expectEqual(@as(?u32, 100), parseLimit("100"));
    try testing.expectEqual(@as(?u32, 5), parseLimit("05"));
    try testing.expectEqual(null, parseLimit("0"));
    try testing.expectEqual(null, parseLimit("101"));
    try testing.expectEqual(null, parseLimit("-1"));
    try testing.expectEqual(null, parseLimit("+1"));
    try testing.expectEqual(null, parseLimit("1_0"));
    try testing.expectEqual(null, parseLimit("99999999999999999999"));
    try testing.expectEqual(null, parseLimit(""));
    try testing.expectEqual(null, parseLimit("ten"));
}

test {
    _ = list_db;
}

//! POST /notes and GET /notes/{id}, plus request helpers shared by the
//! other note endpoints.

const std = @import("std");
const Context = @import("../http/Context.zig");
const note = @import("../note.zig");
const notes_db = @import("../db/notes.zig");

/// POST /notes
pub fn create(ctx: *Context) Context.Error!void {
    const input = try readInput(ctx) orelse return;
    const created = blk: {
        const db = ctx.store.acquire();
        defer ctx.store.release();
        break :blk try notes_db.insert(db, input);
    };
    try ctx.sendJson(.created, created);
}

/// GET /notes/{id}
pub fn get(ctx: *Context) Context.Error!void {
    const id = try idParam(ctx) orelse return;
    const found = blk: {
        const db = ctx.store.acquire();
        defer ctx.store.release();
        break :blk try notes_db.get(db, ctx.arena, id);
    };
    if (found) |n| return ctx.sendJson(.ok, n);
    try sendNotFound(ctx);
}

/// Reads and validates a note from the request body. Answers 400 and
/// returns null if it is invalid.
pub fn readInput(ctx: *Context) Context.Error!?note.Input {
    const body = try ctx.readBody();
    var diag: note.Diagnostic = .{};
    return note.parseInput(ctx.arena, body, &diag) catch |err| switch (err) {
        error.OutOfMemory => |e| return e,
        error.InvalidInput => {
            try ctx.sendError(.bad_request, diag.message);
            return null;
        },
    };
}

/// The `{id}` path parameter. Answers 404 and returns null if it is not a
/// positive integer, since no note can have such an id.
pub fn idParam(ctx: *Context) Context.Error!?i64 {
    if (parseId(ctx.param("id"))) |id| return id;
    try sendNotFound(ctx);
    return null;
}

pub fn sendNotFound(ctx: *Context) Context.Error!void {
    try ctx.sendError(.not_found, "note not found");
}

/// Parses a note id: a positive decimal integer without sign.
pub fn parseId(text: []const u8) ?i64 {
    if (text.len == 0) return null;
    for (text) |ch| if (!std.ascii.isDigit(ch)) return null;
    const id = std.fmt.parseInt(i64, text, 10) catch return null;
    return if (id > 0) id else null;
}

test parseId {
    try std.testing.expectEqual(@as(?i64, 1), parseId("1"));
    try std.testing.expectEqual(@as(?i64, 42), parseId("42"));
    try std.testing.expectEqual(@as(?i64, std.math.maxInt(i64)), parseId("9223372036854775807"));
    try std.testing.expectEqual(null, parseId("9223372036854775808"));
    try std.testing.expectEqual(null, parseId("0"));
    try std.testing.expectEqual(null, parseId("-1"));
    try std.testing.expectEqual(null, parseId("+1"));
    try std.testing.expectEqual(null, parseId("abc"));
    try std.testing.expectEqual(null, parseId("1a"));
    try std.testing.expectEqual(null, parseId("1_0"));
    try std.testing.expectEqual(null, parseId(""));
}

test {
    _ = notes_db;
}

//! GET /stats and GET /tags.

const std = @import("std");
const Context = @import("../http/Context.zig");
const stats_db = @import("../db/stats.zig");
const TagCount = stats_db.TagCount;

/// GET /stats: `{"notes": <count>, "tags": {"<tag>": <count>, ...}}`.
pub fn stats(ctx: *Context) Context.Error!void {
    const notes: i64, const counts: []const TagCount = blk: {
        const db = ctx.store.acquire();
        defer ctx.store.release();
        break :blk .{ try stats_db.noteCount(db), try stats_db.tagCounts(db, ctx.arena, .by_tag) };
    };
    try ctx.sendJson(.ok, .{ .notes = notes, .tags = TagMap{ .counts = counts } });
}

/// GET /tags: `{"tags": [{"tag": "<tag>", "count": <n>}, ...]}`, ordered by
/// count descending, then tag ascending.
pub fn tags(ctx: *Context) Context.Error!void {
    const counts = blk: {
        const db = ctx.store.acquire();
        defer ctx.store.release();
        break :blk try stats_db.tagCounts(db, ctx.arena, .by_count);
    };
    try ctx.sendJson(.ok, .{ .tags = counts });
}

/// Serializes tag counts as a JSON object mapping each tag to its count.
const TagMap = struct {
    counts: []const TagCount,

    pub fn jsonStringify(map: TagMap, jws: anytype) !void {
        try jws.beginObject();
        for (map.counts) |c| {
            try jws.objectField(c.tag);
            try jws.write(c.count);
        }
        try jws.endObject();
    }
};

test TagMap {
    const gpa = std.testing.allocator;

    const empty = try std.json.Stringify.valueAlloc(gpa, .{ .tags = TagMap{ .counts = &.{} } }, .{});
    defer gpa.free(empty);
    try std.testing.expectEqualStrings("{\"tags\":{}}", empty);

    const map: TagMap = .{ .counts = &.{ .{ .tag = "a", .count = 2 }, .{ .tag = "b-1", .count = 1 } } };
    const json = try std.json.Stringify.valueAlloc(gpa, map, .{});
    defer gpa.free(json);
    try std.testing.expectEqualStrings("{\"a\":2,\"b-1\":1}", json);
}

test {
    _ = stats_db;
}

//! The application's database: a single SQLite connection shared by all
//! request handlers, serialized with a mutex.
//!
//! Usage from a handler:
//!
//!     const db = store.acquire();
//!     defer store.release();
//!     // ... queries on `db` ...

const Store = @This();

const std = @import("std");
const Io = std.Io;
const sqlite = @import("sqlite.zig");
const schema = @import("schema.zig");

io: Io,
db: sqlite.Db,
mutex: Io.Mutex = .init,

/// Opens the database at `path`, creating the file and the schema if needed.
pub fn open(io: Io, path: [:0]const u8) sqlite.Error!Store {
    const db = try sqlite.Db.open(path, .{});
    errdefer db.close();
    try db.exec(
        \\PRAGMA journal_mode = WAL;
        \\PRAGMA synchronous = NORMAL;
        \\PRAGMA foreign_keys = ON;
    );
    try schema.migrate(db);
    return .{ .io = io, .db = db };
}

pub fn close(store: *Store) void {
    store.db.close();
    store.* = undefined;
}

/// Gives the calling task exclusive use of the connection until `release`.
pub fn acquire(store: *Store) sqlite.Db {
    store.mutex.lockUncancelable(store.io);
    return store.db;
}

pub fn release(store: *Store) void {
    store.mutex.unlock(store.io);
}

test "open an in-memory store" {
    var store = try Store.open(std.testing.io, ":memory:");
    defer store.close();
    const db = store.acquire();
    defer store.release();
    try db.run("INSERT INTO notes (title) VALUES (?)", .{"t"});
}

//! Data access for replacing and deleting single notes. Functions take a
//! `sqlite.Db` obtained with `Store.acquire`.

const std = @import("std");
const sqlite = @import("sqlite.zig");
const note = @import("../note.zig");
const notes_db = @import("notes.zig");
const Note = note.Note;

/// Replaces the title, body and tags of note `id` in one transaction.
/// Returns the updated note, or null if there is no note with `id`.
pub fn update(db: sqlite.Db, id: i64, input: note.Input) sqlite.Error!?Note {
    try db.begin();
    errdefer db.rollback();
    try db.run("UPDATE notes SET title = ?, body = ? WHERE id = ?", .{ input.title, input.body, id });
    if (db.changes() == 0) {
        db.rollback();
        return null;
    }
    try db.run("DELETE FROM note_tags WHERE note_id = ?", .{id});
    try notes_db.insertTags(db, id, input.tags);
    try db.commit();
    return .{ .id = id, .title = input.title, .body = input.body, .tags = input.tags };
}

/// Deletes note `id` and, through the foreign key, its tags. Returns
/// whether the note existed.
pub fn remove(db: sqlite.Db, id: i64) sqlite.Error!bool {
    try db.run("DELETE FROM notes WHERE id = ?", .{id});
    return db.changes() > 0;
}

const testing = std.testing;

fn openTestDb() !sqlite.Db {
    const db = try sqlite.Db.open(":memory:", .{});
    errdefer db.close();
    try db.exec("PRAGMA foreign_keys = ON");
    try @import("schema.zig").migrate(db);
    return db;
}

test "update replaces title, body and tags" {
    const db = try openTestDb();
    defer db.close();
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();

    _ = try notes_db.insert(db, .{ .title = "old", .body = "text", .tags = &.{ "x", "y" } });
    const updated = (try update(db, 1, .{ .title = "new", .tags = &.{ "a", "y" } })).?;
    try testing.expectEqual(@as(i64, 1), updated.id);

    const got = (try notes_db.get(db, arena.allocator(), 1)).?;
    try testing.expectEqualStrings("new", got.title);
    try testing.expectEqualStrings("", got.body);
    try testing.expectEqual(2, got.tags.len);
    try testing.expectEqualStrings("a", got.tags[0]);
    try testing.expectEqualStrings("y", got.tags[1]);

    _ = (try update(db, 1, .{ .title = "bare" })).?;
    try testing.expectEqual(0, (try notes_db.tagsOf(db, arena.allocator(), 1)).len);
}

test "update of a missing note changes nothing" {
    const db = try openTestDb();
    defer db.close();

    try testing.expectEqual(null, try update(db, 1, .{ .title = "t", .tags = &.{"a"} }));
    var stmt = try db.prepare("SELECT count(*) FROM note_tags");
    defer stmt.deinit();
    try testing.expect(try stmt.step());
    try testing.expectEqual(@as(i64, 0), stmt.columnInt(0));
}

test "remove deletes a note once and its id is not reused" {
    const db = try openTestDb();
    defer db.close();

    _ = try notes_db.insert(db, .{ .title = "a", .tags = &.{"x"} });
    try testing.expect(try remove(db, 1));
    try testing.expect(!try notes_db.exists(db, 1));
    try testing.expect(!try remove(db, 1));
    try testing.expect(!try remove(db, 2));

    const next = try notes_db.insert(db, .{ .title = "b" });
    try testing.expectEqual(@as(i64, 2), next.id);
}

//! Data access for listing notes with filters (GET /notes).

const std = @import("std");
const Allocator = std.mem.Allocator;
const sqlite = @import("sqlite.zig");
const Note = @import("../note.zig").Note;

pub const Error = sqlite.Error || Allocator.Error;

pub const max_limit = 100;

/// Which notes to list. All conditions are combined.
pub const Filter = struct {
    /// Only notes that have this tag.
    tag: ?[]const u8 = null,
    /// Only notes whose title or body contains this text, ignoring ASCII case.
    text: ?[]const u8 = null,
    /// Only notes with an id greater than this.
    after: i64 = 0,
    /// At most this many notes.
    limit: u32 = max_limit,
};

/// Tags are joined with this separator in the query result. It cannot
/// occur in a valid tag (see `note.isValidTag`).
const tag_separator = ',';

// `lower()` and `instr()` without ICU fold only ASCII letters, which is
// exactly the case-insensitivity required, and unlike LIKE there are no
// wildcard characters to escape. The tags come back with each row, sorted,
// so a whole page is read with a single statement.
const list_sql = std.fmt.comptimePrint(
    \\SELECT id, title, body,
    \\       (SELECT group_concat(tag, '{c}' ORDER BY tag) FROM note_tags WHERE note_id = notes.id)
    \\FROM notes
    \\WHERE id > ?1
    \\  AND (?2 IS NULL OR EXISTS (SELECT 1 FROM note_tags WHERE note_id = notes.id AND tag = ?2))
    \\  AND (?3 IS NULL OR instr(lower(title), lower(?3)) > 0 OR instr(lower(body), lower(?3)) > 0)
    \\ORDER BY id
    \\LIMIT ?4
, .{tag_separator});

/// The notes matching `filter`, ordered by id ascending.
pub fn list(db: sqlite.Db, arena: Allocator, filter: Filter) Error![]Note {
    var stmt = try db.prepare(list_sql);
    defer stmt.deinit();
    try stmt.bindAll(.{ filter.after, filter.tag, filter.text, filter.limit });

    var notes: std.ArrayList(Note) = .empty;
    while (try stmt.step()) {
        try notes.append(arena, .{
            .id = stmt.columnInt(0),
            .title = try stmt.columnTextAlloc(arena, 1),
            .body = try stmt.columnTextAlloc(arena, 2),
            .tags = try splitTags(arena, stmt.columnText(3)),
        });
    }
    return notes.toOwnedSlice(arena);
}

fn splitTags(arena: Allocator, joined: []const u8) Allocator.Error![]const []const u8 {
    if (joined.len == 0) return &.{};
    const owned = try arena.dupe(u8, joined);
    const tags = try arena.alloc([]const u8, std.mem.countScalar(u8, owned, tag_separator) + 1);
    var it = std.mem.splitScalar(u8, owned, tag_separator);
    for (tags) |*tag| tag.* = it.next().?;
    return tags;
}

const testing = std.testing;
const notes_db = @import("notes.zig");

fn openTestDb() !sqlite.Db {
    const db = try sqlite.Db.open(":memory:", .{});
    errdefer db.close();
    try db.exec("PRAGMA foreign_keys = ON");
    try @import("schema.zig").migrate(db);
    return db;
}

fn expectIds(want: []const i64, got: []const Note) !void {
    const ids = try testing.allocator.alloc(i64, got.len);
    defer testing.allocator.free(ids);
    for (got, ids) |n, *id| id.* = n.id;
    try testing.expectEqualSlices(i64, want, ids);
}

test "list returns every note with its tags in id order" {
    const db = try openTestDb();
    defer db.close();
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    try expectIds(&.{}, try list(db, a, .{}));

    _ = try notes_db.insert(db, .{ .title = "a" });
    _ = try notes_db.insert(db, .{ .title = "b", .body = "x", .tags = &.{ "a-1", "t", "z" } });

    const all = try list(db, a, .{});
    try expectIds(&.{ 1, 2 }, all);
    try testing.expectEqualStrings("a", all[0].title);
    try testing.expectEqual(0, all[0].tags.len);
    try testing.expectEqualStrings("b", all[1].title);
    try testing.expectEqualStrings("x", all[1].body);
    try testing.expectEqual(3, all[1].tags.len);
    try testing.expectEqualStrings("a-1", all[1].tags[0]);
    try testing.expectEqualStrings("t", all[1].tags[1]);
    try testing.expectEqualStrings("z", all[1].tags[2]);
}

test "list filters by tag, text, after and limit" {
    const db = try openTestDb();
    defer db.close();
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    _ = try notes_db.insert(db, .{ .title = "Hello world", .tags = &.{"greet"} });
    _ = try notes_db.insert(db, .{ .title = "other", .body = "say HELLO", .tags = &.{ "greet", "misc" } });
    _ = try notes_db.insert(db, .{ .title = "100% _done_" });
    _ = try notes_db.insert(db, .{ .title = "Ünïcode", .body = "ÉTÉ" });

    try expectIds(&.{2}, try list(db, a, .{ .tag = "misc" }));
    try expectIds(&.{ 1, 2 }, try list(db, a, .{ .tag = "greet" }));
    try expectIds(&.{}, try list(db, a, .{ .tag = "gree" }));
    try expectIds(&.{ 1, 2 }, try list(db, a, .{ .text = "hello" }));
    try expectIds(&.{ 1, 2 }, try list(db, a, .{ .text = "HeLLo" }));
    try expectIds(&.{2}, try list(db, a, .{ .text = "hello", .tag = "misc" }));
    try expectIds(&.{ 1, 2, 3, 4 }, try list(db, a, .{ .text = "" }));
    // LIKE wildcards are plain characters.
    try expectIds(&.{3}, try list(db, a, .{ .text = "0%" }));
    try expectIds(&.{3}, try list(db, a, .{ .text = "_d" }));
    try expectIds(&.{}, try list(db, a, .{ .text = "%%" }));
    // Only ASCII letters are folded.
    try expectIds(&.{4}, try list(db, a, .{ .text = "Ünï" }));
    try expectIds(&.{}, try list(db, a, .{ .text = "ünï" }));
    try expectIds(&.{4}, try list(db, a, .{ .text = "ÉTÉ" }));
    try expectIds(&.{}, try list(db, a, .{ .text = "été" }));

    try expectIds(&.{ 3, 4 }, try list(db, a, .{ .after = 2 }));
    try expectIds(&.{ 1, 2, 3, 4 }, try list(db, a, .{ .after = -5 }));
    try expectIds(&.{}, try list(db, a, .{ .after = std.math.maxInt(i64) }));
    try expectIds(&.{ 1, 2 }, try list(db, a, .{ .limit = 2 }));
    try expectIds(&.{ 2, 3 }, try list(db, a, .{ .after = 1, .limit = 2 }));
    try expectIds(&.{2}, try list(db, a, .{ .after = 1, .tag = "greet", .text = "say" }));
}

test "list skips deleted notes" {
    const db = try openTestDb();
    defer db.close();
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();

    _ = try notes_db.insert(db, .{ .title = "a", .tags = &.{"x"} });
    _ = try notes_db.insert(db, .{ .title = "b", .tags = &.{"x"} });
    try db.run("DELETE FROM notes WHERE id = ?", .{1});
    try expectIds(&.{2}, try list(db, arena.allocator(), .{ .tag = "x" }));
}

//! Data access for single notes. Functions take a `sqlite.Db` obtained with
//! `Store.acquire` and allocate results in the given (request) arena.

const std = @import("std");
const Allocator = std.mem.Allocator;
const sqlite = @import("sqlite.zig");
const note = @import("../note.zig");
const Note = note.Note;

pub const Error = sqlite.Error || Allocator.Error;

/// Inserts a new note with its tags in one transaction.
pub fn insert(db: sqlite.Db, input: note.Input) sqlite.Error!Note {
    try db.begin();
    errdefer db.rollback();
    try db.run("INSERT INTO notes (title, body) VALUES (?, ?)", .{ input.title, input.body });
    const id = db.lastInsertRowId();
    try insertTags(db, id, input.tags);
    try db.commit();
    return .{ .id = id, .title = input.title, .body = input.body, .tags = input.tags };
}

/// Returns the note with `id`, or null if there is none.
pub fn get(db: sqlite.Db, arena: Allocator, id: i64) Error!?Note {
    var stmt = try db.prepare("SELECT title, body FROM notes WHERE id = ?");
    defer stmt.deinit();
    try stmt.bindAll(.{id});
    if (!try stmt.step()) return null;
    return .{
        .id = id,
        .title = try stmt.columnTextAlloc(arena, 0),
        .body = try stmt.columnTextAlloc(arena, 1),
        .tags = try tagsOf(db, arena, id),
    };
}

/// Whether a note with `id` exists.
pub fn exists(db: sqlite.Db, id: i64) sqlite.Error!bool {
    var stmt = try db.prepare("SELECT 1 FROM notes WHERE id = ?");
    defer stmt.deinit();
    try stmt.bindAll(.{id});
    return stmt.step();
}

/// The tags of note `id`, sorted ascending.
pub fn tagsOf(db: sqlite.Db, arena: Allocator, id: i64) Error![]const []const u8 {
    var stmt = try db.prepare("SELECT tag FROM note_tags WHERE note_id = ? ORDER BY tag");
    defer stmt.deinit();
    try stmt.bindAll(.{id});
    var tags: std.ArrayList([]const u8) = .empty;
    while (try stmt.step()) try tags.append(arena, try stmt.columnTextAlloc(arena, 0));
    return tags.toOwnedSlice(arena);
}

/// Adds `tags` (unique) to note `id`. Call inside a transaction.
pub fn insertTags(db: sqlite.Db, id: i64, tags: []const []const u8) sqlite.Error!void {
    if (tags.len == 0) return;
    var stmt = try db.prepare("INSERT INTO note_tags (note_id, tag) VALUES (?, ?)");
    defer stmt.deinit();
    for (tags) |tag| {
        try stmt.bindAll(.{ id, tag });
        _ = try stmt.step();
        stmt.reset();
    }
}

const testing = std.testing;

fn openTestDb() !sqlite.Db {
    const db = try sqlite.Db.open(":memory:", .{});
    errdefer db.close();
    try db.exec("PRAGMA foreign_keys = ON");
    try @import("schema.zig").migrate(db);
    return db;
}

test "insert assigns increasing ids and get reads notes back" {
    const db = try openTestDb();
    defer db.close();
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();

    const first = try insert(db, .{ .title = "first" });
    const second = try insert(db, .{ .title = "second", .body = "text", .tags = &.{ "a", "b-2" } });
    try testing.expectEqual(@as(i64, 1), first.id);
    try testing.expectEqual(@as(i64, 2), second.id);

    const got = (try get(db, arena.allocator(), 2)).?;
    try testing.expectEqualStrings("second", got.title);
    try testing.expectEqualStrings("text", got.body);
    try testing.expectEqual(2, got.tags.len);
    try testing.expectEqualStrings("a", got.tags[0]);
    try testing.expectEqualStrings("b-2", got.tags[1]);

    const empty = (try get(db, arena.allocator(), 1)).?;
    try testing.expectEqual(0, empty.tags.len);

    try testing.expectEqual(null, try get(db, arena.allocator(), 3));
    try testing.expect(try exists(db, 1));
    try testing.expect(!try exists(db, 3));
}

test "deleting a note deletes its tags and its id is not reused" {
    const db = try openTestDb();
    defer db.close();

    _ = try insert(db, .{ .title = "a", .tags = &.{"x"} });
    try db.run("DELETE FROM notes WHERE id = ?", .{1});
    var stmt = try db.prepare("SELECT count(*) FROM note_tags");
    defer stmt.deinit();
    try testing.expect(try stmt.step());
    try testing.expectEqual(@as(i64, 0), stmt.columnInt(0));

    const next = try insert(db, .{ .title = "b" });
    try testing.expectEqual(@as(i64, 2), next.id);
}

//! Database schema, applied as numbered migrations tracked in
//! `PRAGMA user_version`. Append new migrations; never edit applied ones.

const std = @import("std");
const sqlite = @import("sqlite.zig");

const migrations = [_][:0]const u8{
    // 1: notes and their tags.
    \\CREATE TABLE notes (
    \\    -- AUTOINCREMENT: ids are never reused, also after deleting the newest note.
    \\    id    INTEGER PRIMARY KEY AUTOINCREMENT,
    \\    title TEXT NOT NULL,
    \\    body  TEXT NOT NULL DEFAULT ''
    \\) STRICT;
    \\
    \\CREATE TABLE note_tags (
    \\    note_id INTEGER NOT NULL REFERENCES notes (id) ON DELETE CASCADE,
    \\    tag     TEXT NOT NULL,
    \\    PRIMARY KEY (note_id, tag)
    \\) STRICT, WITHOUT ROWID;
    \\
    \\CREATE INDEX note_tags_by_tag ON note_tags (tag, note_id);
    ,
};

/// Brings the database schema up to date.
pub fn migrate(db: sqlite.Db) sqlite.Error!void {
    const current = std.math.cast(usize, try version(db)) orelse return error.Sqlite;
    if (current > migrations.len) {
        std.log.err("database schema version {d} is newer than this program ({d})", .{ current, migrations.len });
        return error.Sqlite;
    }
    for (migrations[current..], current + 1..) |sql, next| {
        try db.begin();
        errdefer db.rollback();
        try db.exec(sql);
        var buf: [64]u8 = undefined;
        try db.exec(std.fmt.bufPrintZ(&buf, "PRAGMA user_version = {d}", .{next}) catch unreachable);
        try db.commit();
    }
}

fn version(db: sqlite.Db) sqlite.Error!i64 {
    var stmt = try db.prepare("PRAGMA user_version");
    defer stmt.deinit();
    _ = try stmt.step();
    return stmt.columnInt(0);
}

test "migrate creates the schema and is idempotent" {
    const db = try sqlite.Db.open(":memory:", .{});
    defer db.close();
    try migrate(db);
    try migrate(db);
    try std.testing.expectEqual(@as(i64, migrations.len), try version(db));
    try db.run("INSERT INTO notes (title) VALUES (?)", .{"t"});
}

//! A thin, typed wrapper over the SQLite C API.
//!
//! Only the small surface this service needs is exposed: opening a
//! connection, executing SQL, and prepared statements with typed binding and
//! column access. Errors are reported as `error.Sqlite`; the connection's
//! `errorMessage` describes the most recent failure.

const std = @import("std");
const c = @import("sqlite3");

const log = std.log.scoped(.sqlite);

pub const Error = error{Sqlite};

pub const Db = struct {
    handle: *c.sqlite3,

    pub const OpenOptions = struct {
        /// How long a statement waits for a lock held by another connection.
        busy_timeout_ms: c_int = 5000,
    };

    /// Opens (creating if needed) the database at `path`. Use `":memory:"`
    /// for a private in-memory database.
    pub fn open(path: [:0]const u8, options: OpenOptions) Error!Db {
        var handle: ?*c.sqlite3 = null;
        const flags = c.SQLITE_OPEN_READWRITE | c.SQLITE_OPEN_CREATE | c.SQLITE_OPEN_FULLMUTEX;
        const rc = c.sqlite3_open_v2(path.ptr, &handle, flags, null);
        if (rc != c.SQLITE_OK) {
            if (handle) |h| {
                log.err("cannot open {s}: {s}", .{ path, std.mem.span(c.sqlite3_errmsg(h)) });
                _ = c.sqlite3_close_v2(h);
            } else {
                log.err("cannot open {s}: {s}", .{ path, std.mem.span(c.sqlite3_errstr(rc)) });
            }
            return error.Sqlite;
        }
        const db: Db = .{ .handle = handle.? };
        _ = c.sqlite3_extended_result_codes(db.handle, 1);
        _ = c.sqlite3_busy_timeout(db.handle, options.busy_timeout_ms);
        return db;
    }

    pub fn close(db: Db) void {
        _ = c.sqlite3_close_v2(db.handle);
    }

    /// Message describing the most recent failed call on this connection.
    pub fn errorMessage(db: Db) []const u8 {
        return std.mem.span(c.sqlite3_errmsg(db.handle));
    }

    /// Executes one or more SQL statements that return no rows.
    pub fn exec(db: Db, sql: [:0]const u8) Error!void {
        const rc = c.sqlite3_exec(db.handle, sql.ptr, null, null, null);
        if (rc != c.SQLITE_OK) return db.fail("exec");
    }

    /// Compiles a single SQL statement. The caller must `deinit` it.
    pub fn prepare(db: Db, sql: []const u8) Error!Statement {
        var handle: ?*c.sqlite3_stmt = null;
        const rc = c.sqlite3_prepare_v2(db.handle, sql.ptr, @intCast(sql.len), &handle, null);
        if (rc != c.SQLITE_OK) return db.fail("prepare");
        return .{ .db = db, .handle = handle orelse return db.fail("prepare (empty statement)") };
    }

    /// Prepares `sql`, binds `args` and runs it to completion.
    pub fn run(db: Db, sql: []const u8, args: anytype) Error!void {
        var stmt = try db.prepare(sql);
        defer stmt.deinit();
        try stmt.bindAll(args);
        while (try stmt.step()) {}
    }

    /// Rowid of the most recent successful INSERT on this connection.
    pub fn lastInsertRowId(db: Db) i64 {
        return c.sqlite3_last_insert_rowid(db.handle);
    }

    /// Number of rows changed by the most recent INSERT, UPDATE or DELETE.
    pub fn changes(db: Db) i64 {
        return c.sqlite3_changes64(db.handle);
    }

    pub fn begin(db: Db) Error!void {
        try db.exec("BEGIN IMMEDIATE");
    }

    pub fn commit(db: Db) Error!void {
        try db.exec("COMMIT");
    }

    /// Rolls back the open transaction, if any. Meant for `errdefer`, so it
    /// logs instead of returning an error.
    pub fn rollback(db: Db) void {
        if (c.sqlite3_get_autocommit(db.handle) != 0) return;
        db.exec("ROLLBACK") catch {};
    }

    fn fail(db: Db, what: []const u8) error{Sqlite} {
        log.warn("{s}: {s}", .{ what, db.errorMessage() });
        return error.Sqlite;
    }
};

pub const Statement = struct {
    db: Db,
    handle: *c.sqlite3_stmt,

    pub fn deinit(stmt: *Statement) void {
        _ = c.sqlite3_finalize(stmt.handle);
        stmt.* = undefined;
    }

    /// Binds every field of the tuple `args` to parameters 1, 2, ….
    pub fn bindAll(stmt: Statement, args: anytype) Error!void {
        inline for (args, 1..) |arg, index| try stmt.bind(index, arg);
    }

    /// Binds `value` to the 1-based parameter `index`. Supported values are
    /// integers, strings (`[]const u8`), optionals of those, and `null`.
    ///
    /// Strings are bound without copying: they must stay valid until the
    /// statement is reset or finalized.
    pub fn bind(stmt: Statement, index: usize, value: anytype) Error!void {
        const i: c_int = @intCast(index);
        const T = @TypeOf(value);
        const rc = switch (@typeInfo(T)) {
            .null => c.sqlite3_bind_null(stmt.handle, i),
            .optional => if (value) |v| return stmt.bind(index, v) else c.sqlite3_bind_null(stmt.handle, i),
            .int, .comptime_int => c.sqlite3_bind_int64(stmt.handle, i, @intCast(value)),
            .bool => c.sqlite3_bind_int64(stmt.handle, i, @intFromBool(value)),
            else => blk: {
                const text: []const u8 = value;
                break :blk c.sqlite3_bind_text64(stmt.handle, i, text.ptr, text.len, c.SQLITE_STATIC, c.SQLITE_UTF8);
            },
        };
        if (rc != c.SQLITE_OK) return stmt.db.fail("bind");
    }

    /// Advances to the next row. Returns `false` once the statement is done.
    pub fn step(stmt: Statement) Error!bool {
        return switch (c.sqlite3_step(stmt.handle)) {
            c.SQLITE_ROW => true,
            c.SQLITE_DONE => false,
            else => stmt.db.fail("step"),
        };
    }

    /// Resets the statement so it can be executed again with new bindings.
    pub fn reset(stmt: Statement) void {
        _ = c.sqlite3_reset(stmt.handle);
        _ = c.sqlite3_clear_bindings(stmt.handle);
    }

    pub fn columnInt(stmt: Statement, index: usize) i64 {
        return c.sqlite3_column_int64(stmt.handle, @intCast(index));
    }

    /// Text of a column in the current row. The slice is only valid until
    /// the next call to `step`, `reset` or `deinit`; copy it to keep it.
    pub fn columnText(stmt: Statement, index: usize) []const u8 {
        const i: c_int = @intCast(index);
        const ptr = c.sqlite3_column_text(stmt.handle, i) orelse return "";
        const len: usize = @intCast(c.sqlite3_column_bytes(stmt.handle, i));
        return ptr[0..len];
    }

    /// Like `columnText`, but copies the text into `allocator`.
    pub fn columnTextAlloc(stmt: Statement, allocator: std.mem.Allocator, index: usize) error{OutOfMemory}![]u8 {
        return allocator.dupe(u8, stmt.columnText(index));
    }
};

test "exec, bind and read back rows" {
    const db = try Db.open(":memory:", .{});
    defer db.close();

    try db.exec("CREATE TABLE t (n INTEGER NOT NULL, s TEXT)");
    try db.run("INSERT INTO t (n, s) VALUES (?, ?)", .{ 7, "seven" });
    try db.run("INSERT INTO t (n, s) VALUES (?, ?)", .{ 8, null });
    try std.testing.expectEqual(@as(i64, 2), db.lastInsertRowId());

    var stmt = try db.prepare("SELECT n, s FROM t ORDER BY n");
    defer stmt.deinit();
    try std.testing.expect(try stmt.step());
    try std.testing.expectEqual(@as(i64, 7), stmt.columnInt(0));
    try std.testing.expectEqualStrings("seven", stmt.columnText(1));
    try std.testing.expect(try stmt.step());
    try std.testing.expectEqualStrings("", stmt.columnText(1));
    try std.testing.expect(!try stmt.step());
}

test "rollback discards an open transaction" {
    const db = try Db.open(":memory:", .{});
    defer db.close();

    try db.exec("CREATE TABLE t (n INTEGER)");
    try db.begin();
    try db.run("INSERT INTO t VALUES (?)", .{1});
    db.rollback();
    db.rollback(); // no transaction: a no-op

    var stmt = try db.prepare("SELECT count(*) FROM t");
    defer stmt.deinit();
    try std.testing.expect(try stmt.step());
    try std.testing.expectEqual(@as(i64, 0), stmt.columnInt(0));
}

test "errors are reported" {
    const db = try Db.open(":memory:", .{});
    defer db.close();
    try std.testing.expectError(error.Sqlite, db.exec("NOT SQL"));
}

//! Aggregate queries over all notes: the note count and per-tag counts.
//! Functions take a `sqlite.Db` obtained with `Store.acquire` and allocate
//! results in the given (request) arena.

const std = @import("std");
const Allocator = std.mem.Allocator;
const sqlite = @import("sqlite.zig");

pub const Error = sqlite.Error || Allocator.Error;

/// The number of notes that have `tag`.
pub const TagCount = struct {
    tag: []const u8,
    count: i64,
};

pub const Order = enum {
    /// Tag ascending.
    by_tag,
    /// Count descending, then tag ascending.
    by_count,
};

/// The number of notes.
pub fn noteCount(db: sqlite.Db) sqlite.Error!i64 {
    var stmt = try db.prepare("SELECT count(*) FROM notes");
    defer stmt.deinit();
    if (!try stmt.step()) return error.Sqlite;
    return stmt.columnInt(0);
}

/// Every tag in use with the number of notes that have it. Tags of deleted
/// notes are gone with them (`ON DELETE CASCADE`), so they do not count.
pub fn tagCounts(db: sqlite.Db, arena: Allocator, order: Order) Error![]TagCount {
    const sql = switch (order) {
        .by_tag => "SELECT tag, count(*) FROM note_tags GROUP BY tag ORDER BY tag",
        .by_count => "SELECT tag, count(*) AS n FROM note_tags GROUP BY tag ORDER BY n DESC, tag",
    };
    var stmt = try db.prepare(sql);
    defer stmt.deinit();
    var counts: std.ArrayList(TagCount) = .empty;
    while (try stmt.step()) {
        try counts.append(arena, .{
            .tag = try stmt.columnTextAlloc(arena, 0),
            .count = stmt.columnInt(1),
        });
    }
    return counts.toOwnedSlice(arena);
}

const testing = std.testing;
const notes = @import("notes.zig");

fn openTestDb() !sqlite.Db {
    const db = try sqlite.Db.open(":memory:", .{});
    errdefer db.close();
    try db.exec("PRAGMA foreign_keys = ON");
    try @import("schema.zig").migrate(db);
    return db;
}

fn expectCounts(expected: []const TagCount, actual: []const TagCount) !void {
    try testing.expectEqual(expected.len, actual.len);
    for (expected, actual) |e, a| {
        try testing.expectEqualStrings(e.tag, a.tag);
        try testing.expectEqual(e.count, a.count);
    }
}

test "an empty database has no notes and no tags" {
    const db = try openTestDb();
    defer db.close();
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();

    try testing.expectEqual(@as(i64, 0), try noteCount(db));
    try testing.expectEqual(0, (try tagCounts(db, arena.allocator(), .by_tag)).len);
    try testing.expectEqual(0, (try tagCounts(db, arena.allocator(), .by_count)).len);
}

test "tags are counted per note and ordered" {
    const db = try openTestDb();
    defer db.close();
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();

    _ = try notes.insert(db, .{ .title = "a", .tags = &.{ "b", "c" } });
    _ = try notes.insert(db, .{ .title = "b", .tags = &.{ "a", "c" } });
    _ = try notes.insert(db, .{ .title = "c", .tags = &.{ "c", "z" } });
    _ = try notes.insert(db, .{ .title = "d" });

    try testing.expectEqual(@as(i64, 4), try noteCount(db));
    try expectCounts(&.{
        .{ .tag = "a", .count = 1 },
        .{ .tag = "b", .count = 1 },
        .{ .tag = "c", .count = 3 },
        .{ .tag = "z", .count = 1 },
    }, try tagCounts(db, arena.allocator(), .by_tag));
    try expectCounts(&.{
        .{ .tag = "c", .count = 3 },
        .{ .tag = "a", .count = 1 },
        .{ .tag = "b", .count = 1 },
        .{ .tag = "z", .count = 1 },
    }, try tagCounts(db, arena.allocator(), .by_count));
}

test "tags of deleted notes no longer count" {
    const db = try openTestDb();
    defer db.close();
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();

    _ = try notes.insert(db, .{ .title = "a", .tags = &.{ "x", "y" } });
    _ = try notes.insert(db, .{ .title = "b", .tags = &.{"x"} });
    try db.run("DELETE FROM notes WHERE id = ?", .{1});

    try testing.expectEqual(@as(i64, 1), try noteCount(db));
    try expectCounts(&.{.{ .tag = "x", .count = 1 }}, try tagCounts(db, arena.allocator(), .by_count));
}

//! Everything a handler needs to serve one request: the parsed request
//! line, path parameters, a per-request arena, the database, and helpers to
//! read the body and send the response.

const Context = @This();

const std = @import("std");
const Allocator = std.mem.Allocator;
const http = std.http;
const Store = @import("../db/Store.zig");
const query_string = @import("query.zig");

/// Request bodies larger than this are rejected with 413.
pub const max_body_len = 1 << 20;

/// Errors a handler may return. `error.PayloadTooLarge` is answered with
/// 413; read and write failures drop the connection; anything else is
/// logged and answered with 500 if no response was sent yet.
pub const Error = Allocator.Error || error{
    Sqlite,
    PayloadTooLarge,
    ReadFailed,
    WriteFailed,
    HttpExpectationFailed,
};

pub const Param = struct {
    name: []const u8,
    value: []const u8,
};

/// Freed when the request is done.
arena: Allocator,
store: *Store,
request: *http.Server.Request,
method: http.Method,
/// The request path, without the query string. Not decoded.
path: []const u8,
/// The raw query string, without the `?`. Empty if there is none.
query: []const u8,
/// Values of the `{name}` segments of the matched route pattern.
params: []const Param = &.{},
responded: bool = false,

/// Initializes a context for `request`. Copies the request target into
/// `arena`, because reading the body invalidates the request head.
pub fn init(arena: Allocator, store: *Store, request: *http.Server.Request) Allocator.Error!Context {
    const target = try arena.dupe(u8, request.head.target);
    const query_start = std.mem.indexOfScalar(u8, target, '?');
    return .{
        .arena = arena,
        .store = store,
        .request = request,
        .method = request.head.method,
        .path = target[0 .. query_start orelse target.len],
        .query = if (query_start) |i| target[i + 1 ..] else "",
    };
}

/// The value of the path parameter `name`. Asserts the matched route
/// pattern declares it.
pub fn param(ctx: *const Context, name: []const u8) []const u8 {
    for (ctx.params) |p| {
        if (std.mem.eql(u8, p.name, name)) return p.value;
    }
    unreachable;
}

/// The decoded value of the query parameter `name`, or null if absent.
pub fn queryParam(ctx: *const Context, name: []const u8) Allocator.Error!?[]const u8 {
    return query_string.get(ctx.arena, ctx.query, name);
}

/// Reads the whole request body into the arena.
pub fn readBody(ctx: *Context) Error![]const u8 {
    var buf: [4096]u8 = undefined;
    const reader = try ctx.request.readerExpectContinue(&buf);
    return reader.allocRemaining(ctx.arena, .limited(max_body_len)) catch |err| switch (err) {
        error.StreamTooLong => error.PayloadTooLarge,
        error.ReadFailed, error.OutOfMemory => |e| e,
    };
}

/// Sends `value` serialized as JSON.
pub fn sendJson(ctx: *Context, status: http.Status, value: anytype) Error!void {
    const body = try std.json.Stringify.valueAlloc(ctx.arena, value, .{});
    try ctx.send(status, "application/json", body);
}

/// Sends `{"error": message}`.
pub fn sendError(ctx: *Context, status: http.Status, message: []const u8) Error!void {
    try ctx.sendJson(status, .{ .@"error" = message });
}

/// Sends a response without a body, such as 204 No Content.
pub fn sendEmpty(ctx: *Context, status: http.Status) Error!void {
    try ctx.respond(status, "", &.{});
}

pub fn send(ctx: *Context, status: http.Status, content_type: []const u8, body: []const u8) Error!void {
    try ctx.respond(status, body, &.{.{ .name = "content-type", .value = content_type }});
}

/// Sends a response with arbitrary headers. Asserts no response was sent yet.
pub fn respond(ctx: *Context, status: http.Status, body: []const u8, headers: []const http.Header) Error!void {
    std.debug.assert(!ctx.responded);
    ctx.responded = true;
    try ctx.request.respond(body, .{ .status = status, .extra_headers = headers });
}

//! Parsing of URL query strings (`a=1&b=two%20words`).

const std = @import("std");
const Allocator = std.mem.Allocator;

pub const Param = struct {
    /// Raw (still percent-encoded) name and value.
    name: []const u8,
    value: []const u8,
};

/// Iterates over the `name=value` pairs of a query string, without decoding.
/// A pair without `=` has an empty value; empty pairs are skipped.
pub const Iterator = struct {
    rest: []const u8,

    pub fn init(query: []const u8) Iterator {
        return .{ .rest = query };
    }

    pub fn next(it: *Iterator) ?Param {
        while (it.rest.len > 0) {
            const end = std.mem.indexOfScalar(u8, it.rest, '&') orelse it.rest.len;
            const pair = it.rest[0..end];
            it.rest = if (end < it.rest.len) it.rest[end + 1 ..] else "";
            if (pair.len == 0) continue;
            const eq = std.mem.indexOfScalar(u8, pair, '=') orelse pair.len;
            return .{
                .name = pair[0..eq],
                .value = if (eq < pair.len) pair[eq + 1 ..] else "",
            };
        }
        return null;
    }
};

/// Returns the decoded value of the first parameter called `name`, or null
/// if the query has none.
pub fn get(arena: Allocator, query: []const u8, name: []const u8) Allocator.Error!?[]const u8 {
    var it: Iterator = .init(query);
    while (it.next()) |param| {
        const decoded_name = try decode(arena, param.name);
        if (std.mem.eql(u8, decoded_name, name)) return try decode(arena, param.value);
    }
    return null;
}

/// Decodes `+` as a space and `%XX` escapes. Malformed escapes are kept
/// verbatim. Returns `raw` itself when nothing needs decoding.
pub fn decode(arena: Allocator, raw: []const u8) Allocator.Error![]const u8 {
    if (std.mem.indexOfAny(u8, raw, "+%") == null) return raw;
    const buf = try arena.dupe(u8, raw);
    std.mem.replaceScalar(u8, buf, '+', ' ');
    return std.Uri.percentDecodeInPlace(buf);
}

const testing = std.testing;

test Iterator {
    var it: Iterator = .init("a=1&&b&c=x=y&=v");
    const expected = [_]Param{
        .{ .name = "a", .value = "1" },
        .{ .name = "b", .value = "" },
        .{ .name = "c", .value = "x=y" },
        .{ .name = "", .value = "v" },
    };
    for (expected) |want| {
        const got = it.next().?;
        try testing.expectEqualStrings(want.name, got.name);
        try testing.expectEqualStrings(want.value, got.value);
    }
    try testing.expectEqual(null, it.next());
}

test get {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    try testing.expectEqualStrings("hello world", (try get(a, "q=hello+world&tag=x", "q")).?);
    try testing.expectEqualStrings("x", (try get(a, "q=hello+world&tag=x", "tag")).?);
    try testing.expectEqualStrings("a&b", (try get(a, "q=a%26b", "q")).?);
    try testing.expectEqualStrings("first", (try get(a, "q=first&q=second", "q")).?);
    try testing.expectEqualStrings("", (try get(a, "limit=", "limit")).?);
    try testing.expectEqualStrings("%zz", (try get(a, "q=%zz", "q")).?);
    try testing.expectEqual(null, try get(a, "q=1", "tag"));
    try testing.expectEqual(null, try get(a, "", "q"));
}

//! notes: a small HTTP notes service backed by SQLite.
//!
//! Usage: NOTES_DB=<path> notes <port>

const std = @import("std");
const Server = @import("Server.zig");
const Store = @import("db/Store.zig");

pub const std_options: std.Options = .{
    .log_level = .info,
};

pub fn main(init: std.process.Init) !void {
    const io = init.io;
    const arena = init.arena.allocator();

    const args = try init.minimal.args.toSlice(arena);
    if (args.len != 2) std.process.fatal("usage: {s} <port>", .{if (args.len > 0) args[0] else "notes"});
    const port = std.fmt.parseInt(u16, args[1], 10) catch
        std.process.fatal("invalid port: {s}", .{args[1]});

    const db_path = init.environ_map.get("NOTES_DB") orelse
        std.process.fatal("the NOTES_DB environment variable must name the database file", .{});

    var store = Store.open(io, try arena.dupeZ(u8, db_path)) catch
        std.process.fatal("cannot open database {s}", .{db_path});
    defer store.close();

    var server: Server = .{ .gpa = init.gpa, .io = io, .store = &store };
    try server.serve(.{ .ip4 = .loopback(port) });
}

test {
    _ = @import("Server.zig");
    _ = @import("note.zig");
    _ = @import("http/query.zig");
    _ = @import("db/sqlite.zig");
    _ = @import("db/schema.zig");
    _ = @import("db/Store.zig");
    _ = @import("router.zig");
}

//! The note model and the validation rules for client-supplied notes.

const std = @import("std");
const Allocator = std.mem.Allocator;
const json = std.json;

pub const max_title_len = 200;
pub const max_tag_len = 32;

/// A stored note, as returned to clients.
pub const Note = struct {
    id: i64,
    title: []const u8,
    body: []const u8,
    /// Unique and sorted ascending.
    tags: []const []const u8,
};

/// A validated and normalized note, as sent by a client to create or
/// replace a note.
pub const Input = struct {
    title: []const u8,
    body: []const u8 = "",
    /// Unique and sorted ascending.
    tags: []const []const u8 = &.{},
};

/// Explains why `parseInput` rejected a request body.
pub const Diagnostic = struct {
    message: []const u8 = "",
};

pub const ParseError = error{ OutOfMemory, InvalidInput };

/// Parses a JSON request body into a validated `Input`. On
/// `error.InvalidInput`, `diag.message` says what is wrong. The result may
/// reference `bytes` and memory from `arena`.
pub fn parseInput(arena: Allocator, bytes: []const u8, diag: *Diagnostic) ParseError!Input {
    const value = json.parseFromSliceLeaky(json.Value, arena, bytes, .{}) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        else => return invalid(diag, "request body is not valid JSON"),
    };
    return inputFromJson(arena, value, diag);
}

/// Validates an already decoded JSON value; see `parseInput`.
pub fn inputFromJson(arena: Allocator, value: json.Value, diag: *Diagnostic) ParseError!Input {
    const object = switch (value) {
        .object => |o| o,
        else => return invalid(diag, "request body must be a JSON object"),
    };

    const raw_title = switch (object.get("title") orelse return invalid(diag, "title is required")) {
        .string => |s| s,
        else => return invalid(diag, "title must be a string"),
    };
    const title = std.mem.trim(u8, raw_title, &std.ascii.whitespace);
    // The JSON parser guarantees valid UTF-8.
    const title_len = std.unicode.utf8CountCodepoints(title) catch unreachable;
    if (title_len < 1 or title_len > max_title_len) {
        return invalid(diag, std.fmt.comptimePrint("title must be 1-{d} characters", .{max_title_len}));
    }

    const body = if (object.get("body")) |v| switch (v) {
        .string => |s| s,
        else => return invalid(diag, "body must be a string"),
    } else "";

    const tags: []const []const u8 = if (object.get("tags")) |v| switch (v) {
        .array => |array| try parseTags(arena, array.items, diag),
        else => return invalid(diag, "tags must be an array of strings"),
    } else &.{};

    return .{ .title = title, .body = body, .tags = tags };
}

fn parseTags(arena: Allocator, items: []const json.Value, diag: *Diagnostic) ParseError![]const []const u8 {
    const tags = try arena.alloc([]const u8, items.len);
    for (items, tags) |item, *tag| {
        tag.* = switch (item) {
            .string => |s| s,
            else => return invalid(diag, "tags must be an array of strings"),
        };
        if (!isValidTag(tag.*)) {
            return invalid(diag, std.fmt.comptimePrint(
                "each tag must be 1-{d} characters from a-z, 0-9 and -",
                .{max_tag_len},
            ));
        }
    }
    return normalizeTags(tags);
}

/// Whether `tag` is 1–32 characters from `a-z`, `0-9` and `-`.
pub fn isValidTag(tag: []const u8) bool {
    if (tag.len < 1 or tag.len > max_tag_len) return false;
    for (tag) |ch| switch (ch) {
        'a'...'z', '0'...'9', '-' => {},
        else => return false,
    };
    return true;
}

/// Sorts `tags` ascending and removes duplicates, in place. Returns the
/// unique prefix.
pub fn normalizeTags(tags: [][]const u8) [][]const u8 {
    std.mem.sort([]const u8, tags, {}, lessThan);
    var len: usize = 0;
    for (tags) |tag| {
        if (len > 0 and std.mem.eql(u8, tags[len - 1], tag)) continue;
        tags[len] = tag;
        len += 1;
    }
    return tags[0..len];
}

fn lessThan(_: void, a: []const u8, b: []const u8) bool {
    return std.mem.lessThan(u8, a, b);
}

fn invalid(diag: *Diagnostic, message: []const u8) error{InvalidInput} {
    diag.message = message;
    return error.InvalidInput;
}

const testing = std.testing;

fn expectInvalid(bytes: []const u8) !void {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    var diag: Diagnostic = .{};
    try testing.expectError(error.InvalidInput, parseInput(arena.allocator(), bytes, &diag));
    try testing.expect(diag.message.len > 0);
}

test "parseInput applies defaults" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    var diag: Diagnostic = .{};
    const input = try parseInput(arena.allocator(), "{\"title\":\"first\"}", &diag);
    try testing.expectEqualStrings("first", input.title);
    try testing.expectEqualStrings("", input.body);
    try testing.expectEqual(0, input.tags.len);
}

test "parseInput trims the title and normalizes tags" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    var diag: Diagnostic = .{};
    const input = try parseInput(
        arena.allocator(),
        "{\"title\":\"  second \",\"body\":\"text\",\"tags\":[\"work\",\"b-2\",\"work\",\"a\"],\"extra\":1}",
        &diag,
    );
    try testing.expectEqualStrings("second", input.title);
    try testing.expectEqualStrings("text", input.body);
    try testing.expectEqual(3, input.tags.len);
    try testing.expectEqualStrings("a", input.tags[0]);
    try testing.expectEqualStrings("b-2", input.tags[1]);
    try testing.expectEqualStrings("work", input.tags[2]);
}

test "parseInput counts title characters, not bytes" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    var diag: Diagnostic = .{};
    const title = "é" ** max_title_len;
    const input = try parseInput(arena.allocator(), "{\"title\":\"" ++ title ++ "\"}", &diag);
    try testing.expectEqualStrings(title, input.title);
    try expectInvalid("{\"title\":\"" ++ "a" ** (max_title_len + 1) ++ "\"}");
}

test "parseInput rejects invalid bodies" {
    try expectInvalid("");
    try expectInvalid("{\"title\": ");
    try expectInvalid("[]");
    try expectInvalid("\"title\"");
    try expectInvalid("{}");
    try expectInvalid("{\"title\":null}");
    try expectInvalid("{\"title\":5}");
    try expectInvalid("{\"title\":\"   \"}");
    try expectInvalid("{\"title\":\"x\",\"body\":3}");
    try expectInvalid("{\"title\":\"x\",\"body\":null}");
    try expectInvalid("{\"title\":\"x\",\"tags\":\"a\"}");
    try expectInvalid("{\"title\":\"x\",\"tags\":[1]}");
    try expectInvalid("{\"title\":\"x\",\"tags\":[\"Bad\"]}");
    try expectInvalid("{\"title\":\"x\",\"tags\":[\"\"]}");
    try expectInvalid("{\"title\":\"x\",\"tags\":[\"" ++ "a" ** (max_tag_len + 1) ++ "\"]}");
}

test isValidTag {
    try testing.expect(isValidTag("a"));
    try testing.expect(isValidTag("b-2"));
    try testing.expect(isValidTag("a" ** max_tag_len));
    try testing.expect(!isValidTag(""));
    try testing.expect(!isValidTag("A"));
    try testing.expect(!isValidTag("a b"));
    try testing.expect(!isValidTag("a_b"));
    try testing.expect(!isValidTag("a" ** (max_tag_len + 1)));
}

//! The route table: maps request paths and methods to handlers.
//!
//! Each endpoint group lives in its own module under `api/`, so that groups
//! can be developed independently:
//!
//!   api/health.zig  GET /health
//!   api/notes.zig   POST /notes, GET /notes/{id}
//!   api/crud.zig    PUT /notes/{id}, DELETE /notes/{id}
//!   api/list.zig    GET /notes
//!   api/stats.zig   GET /stats, GET /tags

const std = @import("std");
const http = std.http;
const Context = @import("http/Context.zig");

const health = @import("api/health.zig");
const notes = @import("api/notes.zig");
const crud = @import("api/crud.zig");
const list = @import("api/list.zig");
const stats = @import("api/stats.zig");

pub const Handler = *const fn (ctx: *Context) Context.Error!void;

pub const Route = struct {
    /// Path segments separated by `/`; a `{name}` segment matches any
    /// non-empty segment and makes it available as `ctx.param("name")`.
    pattern: []const u8,
    handlers: std.enums.EnumFieldStruct(http.Method, ?Handler, @as(?Handler, null)),
};

pub const routes = [_]Route{
    .{ .pattern = "/health", .handlers = .{ .GET = health.get } },
    .{ .pattern = "/notes", .handlers = .{ .GET = list.list, .POST = notes.create } },
    .{ .pattern = "/notes/{id}", .handlers = .{ .GET = notes.get, .PUT = crud.update, .DELETE = crud.remove } },
    .{ .pattern = "/stats", .handlers = .{ .GET = stats.stats } },
    .{ .pattern = "/tags", .handlers = .{ .GET = stats.tags } },
};

const max_params = 4;

/// Runs the handler for the request's path and method, or answers 404
/// (unknown path) or 405 (known path, unsupported method).
pub fn dispatch(ctx: *Context) Context.Error!void {
    var params: [max_params]Context.Param = undefined;
    inline for (routes) |route| {
        if (match(route.pattern, ctx.path, &params)) |n| {
            ctx.params = params[0..n];
            const handlers = comptime std.EnumArray(http.Method, ?Handler).initDefault(@as(?Handler, null), route.handlers);
            if (handlers.get(ctx.method)) |handler| return handler(ctx);
            const allow = comptime allowHeader(handlers);
            try ctx.respond(.method_not_allowed, "{\"error\":\"method not allowed\"}", &.{
                .{ .name = "content-type", .value = "application/json" },
                .{ .name = "allow", .value = allow },
            });
            return;
        }
    }
    try ctx.sendError(.not_found, "not found");
}

fn allowHeader(comptime handlers: std.EnumArray(http.Method, ?Handler)) []const u8 {
    var allow: []const u8 = "";
    for (std.enums.values(http.Method)) |method| {
        if (handlers.get(method) == null) continue;
        allow = allow ++ (if (allow.len == 0) "" else ", ") ++ @tagName(method);
    }
    return allow;
}

/// Matches `path` against `pattern`, storing `{name}` captures in `params`.
/// Returns the number of captures, or null if the path does not match.
fn match(comptime pattern: []const u8, path: []const u8, params: *[max_params]Context.Param) ?usize {
    var n: usize = 0;
    var want = std.mem.splitScalar(u8, pattern, '/');
    var got = std.mem.splitScalar(u8, path, '/');
    while (want.next()) |segment| {
        const actual = got.next() orelse return null;
        if (segment.len > 2 and segment[0] == '{' and segment[segment.len - 1] == '}') {
            if (actual.len == 0) return null;
            params[n] = .{ .name = segment[1 .. segment.len - 1], .value = actual };
            n += 1;
        } else if (!std.mem.eql(u8, segment, actual)) {
            return null;
        }
    }
    if (got.next() != null) return null;
    return n;
}

test match {
    var params: [max_params]Context.Param = undefined;
    try std.testing.expectEqual(0, match("/notes", "/notes", &params));
    try std.testing.expectEqual(null, match("/notes", "/notes/", &params));
    try std.testing.expectEqual(null, match("/notes", "/note", &params));
    try std.testing.expectEqual(null, match("/notes", "/", &params));

    try std.testing.expectEqual(1, match("/notes/{id}", "/notes/42", &params));
    try std.testing.expectEqualStrings("id", params[0].name);
    try std.testing.expectEqualStrings("42", params[0].value);
    try std.testing.expectEqual(null, match("/notes/{id}", "/notes/", &params));
    try std.testing.expectEqual(null, match("/notes/{id}", "/notes", &params));
    try std.testing.expectEqual(null, match("/notes/{id}", "/notes/1/x", &params));
}

test allowHeader {
    const handlers = comptime std.EnumArray(http.Method, ?Handler).initDefault(@as(?Handler, null), routes[2].handlers);
    try std.testing.expectEqualStrings("GET, PUT, DELETE", comptime allowHeader(handlers));
}

test {
    _ = health;
    _ = notes;
    _ = crud;
    _ = list;
    _ = stats;
}
